# Let me fix the function
input_grid = [
    [5, 8, 7, 8, 5, 5],
    [8, 8, 7, 4, 8, 8],
    [5, 4, 8, 4, 8, 5],
    [8, 7, 8, 8, 8, 8],
    [8, 8, 8, 8, 5, 5],
    [8, 5, 5, 8, 5, 5]
]

n = len(input_grid)

# Build output from scratch (2n x 2n)
output = [[0]*(2*n) for _ in range(2*n)]

# Top-left: original
for r in range(n):
    for c in range(n):
        output[r][c] = input_grid[r][c]

# Top-right: horizontal flip of input
for r in range(n):
    for c in range(n):
        output[r][n + c] = input_grid[r][n - 1 - c]

# Bottom-left: vertical flip of input
for r in range(n):
    for c in range(n):
        output[n + r][c] = input_grid[n - 1 - r][c]

# Bottom-right: 180 degree rotation of input
for r in range(n):
    for c in range(n):
        output[n + r][n + c] = input_grid[n - 1 - r][n - 1 - c]

print("Output grid (12x12):")
for row in output:
    print(row)

